<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$rows=['program_name'=>['Program name','specification_program_name','manual_program_name'],'credit_hours'=>['Credit hours','specification_credit_hours','manual_credit_hours'],'plo_count'=>['PLO count','specification_plo_count','manual_plo_count'],'course_count'=>['Course/curriculum rows','specification_course_count','manual_course_count']];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manual reconciliation</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1200px;margin:auto;padding:1rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd3da;padding:.7rem;vertical-align:top}.conflict{background:#fff3cd}.match{background:#e8f5e9}select,textarea{width:100%;box-sizing:border-box}.errors{color:#a51d2d}.summary{padding:1rem;background:#eef2f5;border-radius:8px}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main><p><a href="/program-manuals/<?=(int)$manual['id']?>">← <?=$h($manual['title'])?></a></p><h1>Specification vs Manual</h1><p class="summary">This workflow records a decision only. It does not silently overwrite either source.</p><?php if($errors):?><div class="errors" role="alert"><?=implode('<br>',array_map($h,$errors))?></div><?php endif;?><form method="post"><?=csrfField()?><div class="scroll"><table><thead><tr><th>Field</th><th>Specification</th><th>Manual</th><th>Resolution</th><th>Explanation</th></tr></thead><tbody><?php foreach($rows as$key=>[$label,$sf,$mf]):$sv=(string)($comparison[$sf]??'');$mv=(string)($comparison[$mf]??'');$same=$sv!==''&&$sv===$mv;$d=$decisions[$key]??[];?><tr class="<?=$same?'match':'conflict'?>"><th scope="row"><?=$h($label)?></th><td><?=$h($sv?:'Not recorded')?></td><td><?=$h($mv?:'Not recorded')?></td><td><select name="resolution[<?=$h($key)?>]" <?=!\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')?'disabled':''?>><?php foreach(['Unresolved','Accept Specification','Accept Manual','Keep Both']as$choice):?><option <?=($d['resolution']??'Unresolved')===$choice?'selected':''?>><?=$h($choice)?></option><?php endforeach;?></select></td><td><textarea name="explanation[<?=$h($key)?>]" rows="3" <?=!\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')?'disabled':''?>><?=$h($d['explanation']??'')?></textarea></td></tr><?php endforeach;?></tbody></table></div><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')):?><p><button type="submit">Save reconciliation decisions</button></p><?php endif;?></form></main></body></html>
